endpoint.request:
employment: {
  ...campi esistenti invariati...,
  product_category_ids?: number[]   // tri-state: chiave assente = non toccare;
                                    // [] = svuota; array = sostituisce l'insieme
}

endpoint.response:
{ success, message, data: { ...user..., employment: {
    ...campi esistenti invariati...,
    product_category_ids: number[],
    product_categories?: [{ id: number, label: string }]  // solo se eager-loaded
} } }

endpoint.request:
{
  domain: 'import_rows' | 'leads' | 'quotes',   // required
  // domain=import_rows: selezione con la STESSA semantica di BulkAssignRequest
  import_run_id?: number,        // required_if:domain,import_rows
  select_all?: boolean,          // default false
  row_ids?: number[],            // target quando select_all=false, esclusioni quando true
  // domain=leads | quotes:
  ids?: number[]                 // required_if:domain,leads|quotes — min:1
}

endpoint.response:
{ success, data: { product_category_ids: number[] } }
// UNIONE dei requisiti dei record selezionati (D-14), ordinata crescente, deduplicata.
// [] significa "nessun requisito": il chiamante NON passa competence_category_ids.

{ success, data: { updated: number, skipped: number } }
// `skipped` (ADDITIVO): righe targettate che `mode=balanced` ha lasciato senza operatore
// perche' nessun operatore della Sede e' competente. Sempre 0 con mode=single.
